import sys

def is_palindrome(s):
    return s == s[::-1]

def count_insertion_positions(s):
    n = len(s)
    if is_palindrome(s):
        return n + 1
    count = 0
    for i in range(n):
        if is_palindrome(s[:i] + s[i+1:]):
            count += 1
    return count

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    results = []
    for i in range(1, T + 1):
        S = input[i]
        results.append(count_insertion_positions(S))
    for result in results:
        print(result)

main()
